package com.logatron.investigation.infrastructure;
import com.logatron.investigation.application.InvestigationPorts.TraceEvidencePort;import com.logatron.investigation.domain.InvestigationModels.DependencyEdge;import com.logatron.logquery.web.LogQueryDtos.LogRow;import com.logatron.tracequery.application.TraceQueryService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.stereotype.Component;import java.util.*;
@Component public class AuthorizedTraceEvidenceAdapter implements TraceEvidencePort {private final TraceQueryService traces;public AuthorizedTraceEvidenceAdapter(TraceQueryService traces){this.traces=traces;}public List<DependencyEdge> dependencies(Jwt jwt,List<LogRow> logs){List<DependencyEdge> out=new ArrayList<>();logs.stream().map(LogRow::traceId).filter(v->v!=null&&!v.isBlank()).distinct().limit(5).forEach(id->{try{var trace=traces.get(jwt,id,(HttpServletRequest)null);Map<String,String> serviceBySpan=new HashMap<>();trace.spans().forEach(s->serviceBySpan.put(s.spanId(),s.service()));trace.spans().forEach(s->{if(s.parentSpanId()!=null&&serviceBySpan.containsKey(s.parentSpanId())&&!Objects.equals(serviceBySpan.get(s.parentSpanId()),s.service()))out.add(new DependencyEdge(serviceBySpan.get(s.parentSpanId()),s.service(),s.operation(),"trace:"+id+":"+s.spanId()));});}catch(RuntimeException ignored){}});return List.copyOf(out);}}

